        stamp = self.started_at.strftime("%Y%m%d_%H%M%S")
        log_dir = os.path.join(app_dir(), "logs")

        self.log_path = os.path.join(
            log_dir,
            f"session_{stamp}.log",
        )
        self.json_path = os.path.join(
            log_dir,
            f"session_{stamp}.json",
        )

        self.events = []

    def add_event(self, kind, message, source="app"):
        event = {
            "timestamp": datetime.datetime.now().isoformat(
                timespec="milliseconds"
            ),
            "kind": kind,
            "source": source,
            "message": message,
        }

        self.events.append(event)
        emit(kind, message)

    def save(self):
        try:
            with open(self.log_path, "w", encoding="utf-8") as file:
                for event in self.events:
                    file.write(
                        f"{event['timestamp']} "
                        f"[{event['kind']}] "
                        f"[{event['source']}] "
                        f"{event['message']}\n"
                    )

            with open(self.json_path, "w", encoding="utf-8") as file:
                json.dump(
                    {
                        "started_at": self.started_at.isoformat(
                            timespec="seconds"
                        ),
                        "events": self.events,
                    },
                    file,
                    indent=2,
                )

            return True

        except Exception as exc:
            log_error(f"Could not save session log: {exc}")
            return False

        
def find_icon():
    d = app_dir()
    try:
        files = os.listdir(d)
    except Exception as e:
        log_error(f"Icon: cannot list {d}: {e}")
        return None
    for name in ICON_NAMES:
        if name in files:
            return os.path.join(d, name)
    lower = {f.lower(): f for f in files}
    for name in ICON_NAMES:
        if name.lower() in lower:
            return os.path.join(d, lower[name.lower()])
    icos = [f for f in files if f.lower().endswith(".ico")]
    if icos:
        return os.path.join(d, icos[0])
    return None

